pub fn is_valid_language(language: &str) -> bool {
    LANGUAGES.iter().any(|item| item.id == language)
}

pub fn voice_locale(voice_id: &str) -> Option<&'static str> {
    VOICES
        .iter()
        .find(|item| item.id == voice_id)
        .and_then(|item| item.languages.first().copied())
}

pub fn is_valid_voice_and_language(voice_id: &str, language: &str) -> bool {
    VOICES
        .iter()
        .any(|item| item.id == voice_id && item.languages.contains(&language))
}

pub fn canonical_voice_name(voice_id: &str) -> Option<String> {
    let locale = voice_locale(voice_id)?;
    let short_actor = voice_id.strip_prefix(locale)?.strip_prefix('-')?;
    Some(format!(
        "Microsoft Server Speech Text to Speech Voice ({locale}, {short_actor})"
    ))
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn catalog_contains_all_international_locales_and_neural_voices() {
        assert_eq!(LANGUAGES.len(), 142);
        assert_eq!(VOICES.len(), 322);
        assert_eq!(LANGUAGES[0].id, "vi-VN");
        assert_eq!(VOICES[0].id, "vi-VN-HoaiMyNeural");
        assert!(is_valid_voice_and_language("vi-VN-HoaiMyNeural", "vi-VN"));
        assert!(is_valid_voice_and_language("vi-VN-NamMinhNeural", "vi-VN"));
        assert!(is_valid_voice_and_language("en-US-EmmaMultilingualNeural", "en-US"));
        assert!(is_valid_voice_and_language("ja-JP-NanamiNeural", "ja-JP"));
        assert!(!is_valid_voice_and_language("vi-VN-HoaiMyNeural", "en-US"));
        assert_eq!(
            canonical_voice_name("vi-VN-HoaiMyNeural").as_deref(),
            Some("Microsoft Server Speech Text to Speech Voice (vi-VN, HoaiMyNeural)")
        );
    }
}
